531	\begin{lemma}[Fact~4.32 of \cite{NW19}]
532	  \label{lem:close-strategies-have-close-values}
533	  Let $\game$ be a nonlocal game, and let $\strategy, \strategy'$ be
534	  two strategies that are $\delta$-close (in the sense of
535	  \Cref{def:strategy-distance}) for $\delta \in [0,1]$, and use the
536	  same state $\ket{\psi}$. If either $\strategy$ or $\strategy'$ is
537	  projective, then $|\val^*(\game,\strategy) - \val^*(\game,
538	  \strategy')| \leq O(\delta^{1/2})$.
539	\end{lemma}
